#!/usr/bin/env bash
# Write infra/.env for the pinned Switch stack, with fresh secrets. Never overwrites an existing file:
# the Postgres volume keeps the first DB_OWNER_PASSWORD, so a new one would lock you out (run `make reset` first).
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV="$ROOT/infra/.env"
if [[ -f "$ENV" ]]; then echo "infra/.env exists; keeping it"; exit 0; fi

hex() { openssl rand -hex "$1"; }
umask 077
cat > "$ENV" <<EOF
# Generated by scripts/gen-env.sh. Contains secrets: never commit.
COMPOSE_PROJECT_NAME=agora
SWITCH_VERSION=0.31.0
SECRET_KEYS=local:$(hex 32)
AGENT_REGISTRATION_TOKEN=$(hex 24)
DB_OWNER_USER=postgres
DB_OWNER_PASSWORD=$(hex 24)
DB_NAME=switch
DB_USER=switch_app
DB_PASSWORD=$(hex 24)
GATEWAY_ADMIN_EMAIL=admin@switch.local
GATEWAY_ADMIN_PASSWORD=$(hex 24)
FRONTEND_BASE_URL=http://localhost:8000
GATEWAY_PUBLIC_URL=http://localhost:8000
MATTERMOST_ADMIN_USER=admin
MATTERMOST_ADMIN_PASSWORD=$(hex 24)
MATTERMOST_TEAM_NAME=switch
MATTERMOST_USER=user
MATTERMOST_USER_PASSWORD=$(hex 24)
EOF
echo "wrote infra/.env (mode 600)"
